const input = $input.first().json;
const body = input.body ?? input;
const id = String(body.id ?? '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) {
  throw new Error('Valid id is required');
}
const actorId = String(input.jwtPayload?.userId ?? input.jwtPayload?.sub ?? '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(actorId)) {
  throw new Error('Valid jwt userId is required');
}
const scope = String(body.scope ?? 'occurrence').trim().toLowerCase();
if (!['occurrence', 'series'].includes(scope)) throw new Error(`Invalid scope: ${body.scope}`);

return [{ json: { id, scope, actor_id: actorId } }];

const row = $input.first().json ?? {};
const parsedId = $('Parse Input3').first().json.id;

if (Number(row.removed) > 0) {
  return [{ json: { success: true, code: 200, id: row.id || parsedId } }];
}

// Ya no existe: la baja optimista del calendario puede reintentar sobre un id borrado.
if (Number(row.found) === 0) {
  return [{ json: { error: true, code: 404, message: 'El ítem ya no existe' } }];
}

return [{ json: { error: true, code: 403, message: 'Solo su autor puede eliminar un ítem personal' } }];
